package dev.kelmagic.client;
import dev.kelmagic.KelMagic;import dev.kelmagic.core.KelLexicon;import dev.kelmagic.network.CodexOpen;import java.util.*;import net.minecraft.client.*;import net.minecraft.client.gui.screens.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;
@EventBusSubscriber(modid=KelMagic.MODID,value=Dist.CLIENT)public final class QaLore {
 static boolean opened;static int wait,stage,frames;static Screen screen;
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.loreQA")||stage>=5)return;var mc=Minecraft.getInstance();if(mc.level==null){if(!opened&&mc.screen instanceof TitleScreen&&++wait>40){opened=true;mc.createWorldOpenFlows().openWorld("KelMagicQA",()->{});}return;}if(screen==null){mc.options.guiScale().set(2);mc.resizeDisplay();int[] pages={3,84,3,4,15};screen=new CodexScreen(new CodexOpen(new ArrayList<>(KelLexicon.WORDS.keySet()),List.of(),false,stage<2?0:1,pages[stage],"","qa-lore"));mc.setScreen(screen);}if(++frames==16){var dir=new java.io.File("/data/native-qa-1.13");dir.mkdirs();Screenshot.grab(dir,String.format("lore-%02d.png",stage),mc.getMainRenderTarget(),m->{});}if(frames>=24){frames=0;if(stage==4&&Boolean.getBoolean("kelmagic.locateQA")&&!QaLocate.done)return;screen=null;if(++stage==5){System.out.println("LORE_NATIVE_QA_113_COMPLETE");mc.stop();}}}
}
